module LIFObuffer (
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output reg EMPTY,
    output reg FULL,
    output reg [3:0] dataOut
);

reg [3:0] buffer [0:3];
integer top;

assign EMPTY = (top == -1);
assign FULL = (top == 3);

always @(posedge Clk or posedge Rst) begin
    if (Rst) begin
        top <= -1;
        dataOut <= 4'b0000;
    end else begin
        if (EN) begin
            if (!FULL && !RW) begin
                buffer[top + 1] <= dataIn;
                top <= top + 1;
            end else if (!EMPTY && RW) begin
                dataOut <= buffer[top];
                top <= top - 1;
            end
        end
    end
end

endmodule
